#!/usr/bin/env python3\n"""\nBacktest Justin EMA9 strategies on majors.\nDaily proxy for 5m/15m tournament style.\n"""\n\nimport math\nimport json\nimport sys\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nimport yfinance as yf\n\n\ndef binomial_p(wins: int, n: int, p_null: float = 0.5) -> float:\n    if n == 0:\n        return 1.0\n    p_val = 0.0\n    for k in range(wins, n + 1):\n        p_val += math.comb(n, k) * (p_null ** k) * ((1 - p_null) ** (n - k))\n    return p_val\n\n\ndef calc_sharpe(pnls: list, annualize: float = 252.0) -> float:\n    if len(pnls) < 2:\n        return 0.0\n    arr = np.array(pnls)\n    mean = np.mean(arr)\n    std = np.std(arr, ddof=1)\n    if std == 0:\n        return 0.0\n    return float((mean / std) * np.sqrt(annualize))\n\n\ndef fetch_data(symbol: str, period: str = "5y") -> pd.DataFrame:\n    df = yf.download(symbol, period=period, interval="1d",\n                     auto_adjust=True, progress=False)\n    if isinstance(df.columns, pd.MultiIndex):\n        df.columns = df.columns.get_level_values(0)\n    df = df.dropna()\n    return df\n\n\ndef ema(series: pd.Series, period: int) -> pd.Series:\n    return series.ewm(span=period, adjust=False).mean()\n\n\ndef rsi(series: pd.Series, period: int) -> pd.Series:\n    delta = series.diff()\n    gain = (delta.where(delta > 0, 0)).rolling(window=period).mean()\n    loss = (-delta.where(delta < 0, 0)).rolling(window=period).mean()\n    rs = gain / loss\n    return 100 - (100 / (1 + rs))\n\n\ndef atr(high: pd.Series, low: pd.Series, close: pd.Series, period: int) -> pd.Series:\n    tr1 = high - low\n    tr2 = abs(high - close.shift())\n    tr3 = abs(low - close.shift())\n    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)\n    return tr.ewm(span=period, adjust=False).mean()\n\n\ndef volume_ratio(volume: pd.Series, period: int = 20) -> pd.Series:\n    avg_vol = volume.rolling(period).mean()\n    return volume / avg_vol\n\n\ndef hma(series: pd.Series, period: int) -> pd.Series:\n    wma1 = series.ewm(span=period//2, adjust=False).mean() * 2\n    wma2 = series.ewm(span=period, adjust=False).mean()\n    raw = wma1 - wma2\n    sqrt_n = int(period**0.5)\n    return raw.ewm(span=sqrt_n, adjust=False).mean()\n\n\ndef report(name: str, results: dict):\n    print(f"\\n{'='*60}")\n    print(f"  BACKTEST: {name} on {results['symbol']} ({results.get('period', '5y')})")\n    print(f"{'='*60}")\n    n = results["n_trades"]\n    if n == 0:\n        print("  No trades generated.")\n        return\n    wr = results["win_rate"]\n    sig = results["significant"]\n    sig_mark = "[Y] SIGNIFICANT" if sig else "[X] Not significant"\n    print(f"  Total trades:   {n}")\n    print(f"  Win rate:       {wr*100:.1f}% {sig_mark}")\n    print(f"  Avg P&L/trade:  {results['avg_pnl_pct']:+.3f}%")\n    print(f"  Total return:   {results['total_return_pct']:+.1f}%")\n    print(f"  Sharpe ratio:   {results['sharpe']:.3f}")\n    print(f"  Binomial p:     {results['binomial_p']:.6f}")\n    print(f"  Avg hold time:  {results['avg_days_held']:.1f} days")\n    print(f"  Max consec loss: {results.get('max_consec_loss', 'N/A')}")\n    trades = results.get("trades", [])\n    if trades:\n        print(f"\\n  Last 5 trades:")\n        for t in trades[-5:]:\n            w = "WIN" if t["won"] else "LOSS"\n            print(f"    {t['entry_date']} -> {t['exit_date']}  "\n                  f"{t['pnl_pct']:+.2f}%  [{w}]  {t['exit_reason']}")\n    print()\n\n\ndef summarize_trades(trades: list, symbol: str, period: str = "5y") -> dict:\n    n = len(trades)\n    if n == 0:\n        return {"symbol": symbol, "period": period, "n_trades": 0,\n                "win_rate": 0, "avg_pnl_pct": 0, "total_return_pct": 0,\n                "sharpe": 0, "binomial_p": 1.0, "significant": False,\n                "avg_days_held": 0, "max_consec_loss": 0, "trades": []}\n\n    wins = sum(1 for t in trades if t["won"])\n    pnls = [t["pnl_pct"] for t in trades]\n    days = [t["days"] for t in trades]\n\n    max_cl = 0\n    cl = 0\n    for t in trades:\n        if not t["won"]:\n            cl += 1\n            max_cl = max(max_cl, cl)\n        else:\n            cl = 0\n\n    return {\n        "symbol": symbol,\n        "period": period,\n        "n_trades": n,\n        "win_rate": round(wins / n, 4),\n        "avg_pnl_pct": round(np.mean(pnls), 4),\n        "total_return_pct": round(sum(pnls), 2),\n        "sharpe": round(calc_sharpe(pnls), 3),\n        "binomial_p": round(binomial_p(wins, n), 6),\n        "significant": binomial_p(wins, n) < 0.05,\n        "avg_days_held": round(np.mean(days), 1),\n        "max_consec_loss": max_cl,\n        "trades": trades[-20:],\n    }\n\n\ndef backtest_justin_ema9(symbol: str = "BTC-USD", period: str = "5y", variant: str = "basic") -> dict:\n    df = fetch_data(symbol, period)\n    if len(df) < 250:\n        return summarize_trades([], symbol, period)\n\n    close = df["Close"]\n    high = df["High"]\n    low = df["Low"]\n    volume = df.get("Volume", pd.Series(1.0, index=df.index))\n    dates = df.index\n\n    ema9 = ema(close, 9)\n    rsi14 = rsi(close, 14)\n    vol_r = volume_ratio(volume, 20)\n    atr14 = atr(high, low, close, 14)\n\n    if variant == "hma":\n        hma21 = hma(close, 21)\n        hma_slope = np.sign(hma21.diff())\n\n    trades = []\n    in_long = False\n    in_short = False\n    entry_price = 0.0\n    entry_date = None\n    entry_idx = 0\n    tp_price = 0.0\n    sl_price = 0.0\n\n    for i in range(20, len(close)):\n        c = close.iloc[i]\n        h = high.iloc[i]\n        l = low.iloc[i]\n        v_r = vol_r.iloc[i]\n        r = rsi14.iloc[i]\n        e9 = ema9.iloc[i]\n        atr_v = atr14.iloc[i]\n        h_slope = hma_slope.iloc[i] if variant == "hma" else 1.0  # default pass\n\n        if not in_long and not in_short:\n            # Long entry\n            cross_long = close.iloc[i-1] <= ema9.iloc[i-1] and c > e9\n            rsi_ok_long = r > 45\n            vol_ok = v_r > 1.2\n            hma_ok_long = h_slope > 0 if variant == "hma" else True\n            if cross_long and rsi_ok_long and vol_ok and hma_ok_long:\n                entry_price = c\n                tp_price = c + 2.5 * atr_v\n                sl_price = c - 1.5 * atr_v\n                in_long = True\n                entry_idx = i\n                entry_date = dates[i]\n            # Short entry\n            cross_short = close.iloc[i-1] >= ema9.iloc[i-1] and c < e9\n            rsi_ok_short = r < 55\n            if cross_short and rsi_ok_short and vol_ok and (h_slope < 0 if variant == "hma" else True):\n                entry_price = c\n                tp_price = c - 2.5 * atr_v\n                sl_price = c + 1.5 * atr_v\n                in_short = True\n                entry_idx = i\n                entry_date = dates[i]\n        elif in_long:\n            pnl_pct = (c - entry_price) / entry_price * 100\n            days_held = i - entry_idx\n            exit_reason = None\n            if c <= sl_price:\n                exit_reason = "stop_loss"\n            elif c >= tp_price:\n                exit_reason = "take_profit"\n            elif close.iloc[i] < ema9.iloc[i]:  # reverse cross exit\n                exit_reason = "ema_reverse"\n            elif days_held >= 20:\n                exit_reason = "max_hold"\n            if exit_reason:\n                pnl = (c - entry_price) / entry_price * 100\n                trades.append({\n                    "entry_date": str(entry_date.date()),\n                    "exit_date": str(dates[i].date()),\n                    "entry": round(entry_price, 4),\n                    "exit": round(c, 4),\n                    "pnl_pct": round(pnl, 4),\n                    "days": days_held,\n                    "won": pnl > 0,\n                    "direction": "long",\n                    "exit_reason": exit_reason,\n                })\n                in_long = False\n        elif in_short:\n            pnl_pct = (entry_price - c) / entry_price * 100\n            days_held = i - entry_idx\n            exit_reason = None\n            if c >= sl_price:\n                exit_reason = "stop_loss"\n            elif c <= tp_price:\n                exit_reason = "take_profit"\n            elif close.iloc[i] > ema9.iloc[i]:  # reverse\n                exit_reason = "ema_reverse"\n            elif days_held >= 20:\n                exit_reason = "max_hold"\n            if exit_reason:\n                pnl = (entry_price - c) / entry_price * 100\n                trades.append({\n                    "entry_date": str(entry_date.date()),\n                    "exit_date": str(dates[i].date()),\n                    "entry": round(entry_price, 4),\n                    "exit": round(c, 4),\n                    "pnl_pct": round(pnl, 4),\n                    "days": days_held,\n                    "won": pnl > 0,\n                    "direction": "short",\n                    "exit_reason": exit_reason,\n                })\n                in_short = False\n\n    return summarize_trades(trades, symbol, period)\n\n\nif __name__ == "__main__":\n    symbols = ["BTC-USD", "ETH-USD", "SOL-USD"]\n    variants = ["basic", "hma"]\n\n    print("Justin EMA9 Backtest Results (Daily proxy for 5m/15m)\\n")\n\n    for sym in symbols:\n        for var in variants:\n            res = backtest_justin_ema9(sym, variant=var)\n            report(f"Justin EMA9 ({var}) on {sym}", res)